4.4.2 编写 encode() 编码方法
现在把上面的位运算逻辑组装成工业级方法。 注意方法的签名设计：因为输出长度只有在运行时才知道，我们必须传入 allocator: std.mem.Allocator，在堆上申请返回切片。
pub fn encode(self: Base64,
              allocator: std.mem.Allocator,
              input: []const u8) ![]u8 {

    if (input.len == 0) {
        return "";
    }

    const n_out = try _calc_encode_length(input);
    var out = try allocator.alloc(u8, n_out);
    var buf = [3]u8{ 0, 0, 0 };
    var count: u8 = 0;
    var iout: u64 = 0;

    for (input, 0..) |_, i| {
        buf[count] = input[i];
        count += 1;
        if (count == 3) {
            out[iout] = self._char_at(buf[0] &gt;&gt; 2);
            out[iout + 1] = self._char_at(
                ((buf[0] & 0x03) &lt;&lt; 4) + (buf[1] &gt;&gt; 4)
            );
            out[iout + 2] = self._char_at(
                ((buf[1] & 0x0f) &lt;&lt; 2) + (buf[2] &gt;&gt; 6)
            );
            out[iout + 3] = self._char_at(buf[2] & 0x3f);
            iout += 4;
            count = 0;
        }
    }

    if (count == 1) {
        out[iout] = self._char_at(buf[0] &gt;&gt; 2);
        out[iout + 1] = self._char_at(
            (buf[0] & 0x03) &lt;&lt; 4
        );
        out[iout + 2] = '=';
        out[iout + 3] = '=';
    }

    if (count == 2) {
        out[iout] = self._char_at(buf[0] &gt;&gt; 2);
        out[iout + 1] = self._char_at(
            ((buf[0] & 0x03) &lt;&lt; 4) + (buf[1] &gt;&gt; 4)
        );
        out[iout + 2] = self._char_at(
            (buf[1] & 0x0f) &lt;&lt; 2
        );
        out[iout + 3] = '=';
        iout += 4;
    }

    return out;
}

4.5 构建解码器逻辑
搞定编码器后，解码器的逻辑就顺理成章了。

4.5.1 字符反查索引：_char_index()
收到一个 Base64 字符（比如 'k'），我们得反查出它在 64 码表里的数值是多少。 这里写个朴素实用的扫描查找方法，如果是 = 则返回 64（越界哨兵）：
fn _char_index(self: Base64, char: u8) u8 {
    if (char == '=')
        return 64;

    var i: u8 = 0;
    var output_index: u8 = 0;

    while (i &lt; 64) : (i += 1) {
        if (self._char_at(i) == char)
            break;
        output_index += 1;
    }

    return output_index;
}


4.5.2 解码逆向位移还原
每次吃进 4 个字符查得的索引 buf[0..4]，通过逆向位移拼成原始 3 字节：

output[0] = (buf[0] &lt;&lt; 2) + (buf[1] &gt;&gt; 4);
output[1] = (buf[1] &lt;&lt; 4) + (buf[2] &gt;&gt; 2);
output[2] = (buf[2] &lt;&lt; 6) + buf[3];

